"""Bookings smoke: 1 case, one test each."""

import pytest

from api_test_framework import Expect, unique_id


@pytest.mark.functional
@pytest.mark.smoke
@pytest.mark.writes
@pytest.mark.case("TC030")
@pytest.mark.priority("P2")
def test_tc030_create_and_read_a_booking(api, context):
    """Create and read a booking. Criteria: AC-1."""
    unique = unique_id()
    # 1. POST /bookings: Create
    response = api.post("/bookings", json={
        "passenger_name": f"Meera {unique}",
        "email": f"meera.{unique}@testdata.example",
        "amount": 120,
    })
    Expect(response).status_is(201).field_equals("status", "active")
    context.remember("pnr", response.value("pnr"))
    # 2. GET /bookings/{{pnr}}: Read
    response = api.get(f"/bookings/{context.get('pnr')}")
    (Expect(response).status_is(200)
        .field_equals("amount", 120)
        .field_contains("email", "@testdata.example")
        .responded_within(2000))
